/* Entry and optional local onboarding. No server identity or password collection. */
const $=s=>document.querySelector(s), KEY='lvxing-local-profile-v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let ready=!!window.LXReady, launching=false;
const portal=document.createElement('div');portal.id='portal';document.body.append(portal);
const policy='https://www.changzhou.gov.cn/gi_news/654175548274283';
const reply='https://jtj.changzhou.gov.cn/index.php?a=show&c=phone&catid=14478&id=219655';
function profile(){try{return JSON.parse(localStorage.getItem(KEY)||'null')}catch{return null}}
function city(){return `<svg class="portal-city" viewBox="0 0 760 530" role="img" aria-label="绿色交通与产业研究的城市示意图"><defs><linearGradient id="ptower" x2="0" y2="1"><stop stop-color="#c9ead6"/><stop offset="1" stop-color="#397566"/></linearGradient><pattern id="pgrid" width="48" height="28" patternUnits="userSpaceOnUse"><path d="M0 14 24 0 48 14 24 28Z" fill="none" stroke="#a7ceb5" stroke-opacity=".12"/></pattern></defs><ellipse cx="394" cy="348" rx="320" ry="162" fill="#225144"/><path d="M20 260 387 63 744 261 390 489Z" fill="url(#pgrid)"/><g stroke="#c4e4cc" stroke-opacity=".48" fill="url(#ptower)" stroke-linejoin="round"><path d="M205 292V155l71-39 64 35v137l-66 39Z M205 155l69 37 66-41 M274 192v135"/><path d="M375 261V54l77-42 73 40v207l-74 41Z M375 54l76 42 74-44 M451 96v204"/><path d="M531 339V205l54-29 54 29v134l-54 30Z M531 205l54 30 54-30 M585 235v134"/><path d="M111 343V274l45-24 44 24v69l-45 24Z M111 274l44 24 45-24 M155 298v69"/></g><g stroke="#d9f399" stroke-width="4" opacity=".7"><path d="m218 182 39 21m-39 4 39 21m-39 4 39 21m131-166 44 24m-44 4 44 24m-44 4 44 24m-44 4 44 24m-44 4 44 24m113 30 27 14m-27 9 27 14"/></g><path d="m66 361 131 73 173-95 125 68 174-97" fill="none" stroke="#72b892" stroke-width="20" stroke-opacity=".3"/><path class="portal-flow" d="m66 361 131 73 173-95 125 68 174-97" fill="none" stroke="#ddf4a0" stroke-width="3"/><g fill="#d9f39d"><circle cx="66" cy="361" r="7"/><circle cx="197" cy="434" r="7"/><circle cx="370" cy="339" r="7"/><circle cx="495" cy="407" r="7"/><circle cx="669" cy="310" r="7"/></g><g fill="#84bd97"><circle cx="340" cy="423" r="17"/><circle cx="704" cy="335" r="20"/><circle cx="103" cy="387" r="13"/></g></svg>`}
function nav(){return `<nav class="portal-nav"><a href="#home" class="portal-logo"><img src="logo.svg" alt="">绿行智研<span>RESEARCH STUDIO</span></a><div><a href="#home" data-portal="case">研究案例</a><a href="#home" data-portal="workflow">产品流程</a><button data-portal="register" class="portal-nav-cta">进入工作区 ↗</button></div></nav>`}
function home(){let p=profile();return `${nav()}<main class="portal-home"><section class="portal-hero"><div class="portal-hero-copy"><div class="portal-eyebrow"><i></i> 绿色交通 · 产业链影响分析</div><h1>从一项政策，<br>看清一门生意。</h1><p>把政策、出行行为与企业经营连在一起。<br>找依据、改参数、看结果，再把研究带走。</p><div class="portal-buttons"><button class="portal-primary" data-portal="launch">${p?'继续研究':'跳过，直接体验'} <span>↗</span></button><button class="portal-secondary" data-portal="register">创建个人工作区</button></div><div class="portal-proofline"><span>01 政策有出处</span><span>02 模型可交互</span><span>03 结果可复算</span></div></div><div class="portal-visual">${city()}<div class="portal-float pf-top"><small>POLICY SIGNAL</small><b>城市政策 → 经营影响</b><span>常州 · 永安行 · 共享出行</span></div><div class="portal-float pf-bottom"><small>RESEARCH PATH</small><div><span>政策</span><em>→</em><span>需求</span><em>→</em><span>结算</span></div></div><div class="portal-orbit-label">GREEN MOBILITY<br>RESEARCH / 01</div></div><div class="portal-hero-index">SCROLL TO EXPLORE <span>↓</span></div></section><section class="portal-case" id="portalCase"><div class="portal-section-title"><div><small>01 / WHY THIS CASE</small><h2>使用量增加，收入就会增加吗？</h2></div><p>沿着公开资料追问，<br>把“政策利好”拆成具体问题。</p></div><div class="portal-facts"><a href="${reply}" target="_blank" rel="noopener"><span>公共服务需求</span><strong>290<em>万人次</em></strong><p>2024年五分钟免费骑行量</p><small>常州市交通运输局 · 2025.07.17 ↗</small></a><a href="${policy}" target="_blank" rel="noopener"><span>绿色出行目标</span><strong>80<em>%</em></strong><p>到2030年的绿色出行比例目标</p><small>常州市国家碳达峰试点实施方案 ↗</small></a><a href="https://static.cninfo.com.cn/finalpage/2026-05-16/1225311608.PDF#page=57" target="_blank" rel="noopener"><span>城市业务变化</span><strong>2,934.75<em>万元</em></strong><p>永安行2025年常州共享出行业务收入</p><small>审核问询函回复 · 原PDF第57页 ↗</small></a></div><div class="portal-question"><span>研究问题</span><p>新增需求由谁付费？费用怎样结算？增长能否覆盖成本？</p><button data-portal="launch">进入案例 →</button></div></section><section class="portal-workflow" id="portalWorkflow"><div class="portal-section-title"><div><small>02 / ONE CONNECTED WORKSPACE</small><h2>一条研究路径，四个关键动作。</h2></div><span class="portal-stamp">从原始资料到研究备忘录</span></div><div class="portal-steps">${[['01','找到依据','资料中心','PDF逐页解析、关键词定位、事实口径核对。','⌕'],['02','拆解影响','政策传导','研究范围、政策事件、需求与结算路径。','↗'],['03','改变条件','计算工作台','碳核算、行为曲线、量价拆解与情景对比。','ƒ'],['04','留下结论','研究交付','备忘录、计算底稿、参数快照与运行记录。','≡']].map(([n,t,c,d,icon])=>`<article><div><small>${n}</small><b>${icon}</b></div><span>${c}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></section><section class="portal-bottom"><div><small>START WITH A QUESTION.</small><h2>别只看结论。<br>亲手改一个参数。</h2></div><button class="portal-primary" data-portal="launch">打开研究工作台 ↗</button></section></main><footer class="portal-footer"><span>绿行智研团队 · 北京城市学院</span><span>本地工作区 · 资料保存在当前浏览器</span><a href="https://github.com/lizexuan581-stack/lvxing-research-studio" target="_blank" rel="noopener">开源代码 ↗</a></footer>`}
function register(){const p=profile()||{};return `${nav()}<main class="portal-onboarding"><section class="portal-welcome"><small>YOUR RESEARCH STARTS HERE</small><h1>你好，<br>下一位研究者。</h1><p>一个问题、一组参数、一次新的发现。<br>从这里开始你的绿色交通研究。</p>${city()}<div class="portal-welcome-note">01 资料整理　 /　 02 条件推演　 /　 03 研究交付</div></section><section class="portal-register"><span class="portal-kicker">工作区设置 · 可跳过</span><h2>创建个人工作区</h2><p>填写展示信息，开启你的研究桌面。</p><form id="portalForm"><label>你的称呼<input name="nickname" placeholder="怎么称呼你？" maxlength="24" required value="${esc(p.nickname||'')}"></label><label>学校或团队<input name="organization" placeholder="例如：绿行智研团队" maxlength="60" value="${esc(p.organization||'')}"></label><fieldset><legend>研究角色</legend><label><input type="radio" name="role" value="研究成员" checked><span>研究成员</span></label><label><input type="radio" name="role" value="指导教师"><span>指导教师</span></label><label><input type="radio" name="role" value="体验访客"><span>体验访客</span></label></fieldset><p class="portal-local-note">展示信息仅保存于当前浏览器，无需手机号或密码。</p><p id="portalFormStatus" role="status"></p><button type="submit" class="portal-primary">创建并进入 <span>↗</span></button></form><button class="portal-skip" data-portal="launch">跳过，直接体验 →</button><a class="portal-back" href="#home">← 返回首页</a></section></main>`}
function loading(){return `<main class="portal-launch" role="status" aria-live="polite"><div class="portal-launch-orbit"><i></i><i></i><img src="logo.svg" alt="绿行智研"></div><small>OPENING YOUR WORKSPACE</small><h1>把问题交给研究。</h1><p id="portalLoadText">正在打开本地案例与计算工作台…</p><div class="portal-load-track"><span></span></div><div class="portal-load-stages"><span>① 打开工作区</span><span>② 检查页面资源</span><span>③ 进入案例</span></div><button class="portal-secondary" data-portal="cancel">返回首页</button></main>`}
function updateBadge(){let p=profile();let b=$('.team-badge div');if(b&&p){b.textContent=p.nickname;const small=document.createElement('small');small.textContent=p.organization||p.role;b.append(small)}}
function show(){const page=location.hash.slice(1);const visible=!page||['home','register','launch'].includes(page);document.body.classList.toggle('portal-open',visible);portal.hidden=!visible;$('.app-shell').inert=visible;if(!visible){launching=false;document.title=($('#routeLabel')?.textContent||'研究工作区')+' · 绿行智研';updateBadge();return}document.title=(page==='register'?'创建工作区':'绿行智研 · 从政策到经营');portal.innerHTML=page==='register'?register():page==='launch'?loading():home();if(page==='register')$('#portalForm').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);const nickname=String(d.get('nickname')).trim();if(!nickname){$('#portalFormStatus').textContent='请填写称呼，或选择下方的跳过。';return}try{localStorage.setItem(KEY,JSON.stringify({nickname,organization:String(d.get('organization')).trim(),role:d.get('role')}))}catch{$('#portalFormStatus').textContent='当前无法保存展示信息，可以跳过并体验。';return}launch()});if(page==='launch')finishLaunch()}
function launch(){if(location.hash==='#launch'){finishLaunch();return}location.hash='launch'}
async function finishLaunch(){if(launching)return;launching=true;if(!ready){await new Promise(resolve=>window.addEventListener('lx:ready',resolve,{once:true}))}if(location.hash!=='#launch'){launching=false;return}$('#portalLoadText').textContent='案例与计算模块已就绪，正在进入…';await document.fonts.ready;await new Promise(requestAnimationFrame);await new Promise(requestAnimationFrame);if(location.hash==='#launch')location.hash='overview';launching=false}
portal.addEventListener('click',e=>{const b=e.target.closest('[data-portal]');if(!b)return;const action=b.dataset.portal;e.preventDefault();if(action==='launch')launch();else if(action==='register')location.hash='register';else if(action==='cancel')location.hash='home';else {const scroll=()=>$('#'+(action==='case'?'portalCase':'portalWorkflow'))?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});if(!$('#portalCase')){location.hash='home';window.addEventListener('hashchange',()=>requestAnimationFrame(scroll),{once:true})}else scroll()}});
window.addEventListener('lx:ready',()=>{ready=true;updateBadge();if(document.body.classList.contains('portal-open'))document.title=location.hash==='#register'?'创建工作区':'绿行智研 · 从政策到经营'});window.addEventListener('lx:error',()=>{const p=$('#portalLoadText');if(p)p.textContent='工作区暂未打开，请返回首页并刷新重试。'});window.addEventListener('hashchange',()=>{show();window.scrollTo(0,0)});
document.querySelector('.brand').href='#home';
const entry=document.createElement('a');entry.href='#home';entry.className='portal-home-link';entry.textContent='← 产品首页';$('.side-footer').prepend(entry);
show();
